"use client"

import Link from "next/link"
import { ArrowRight } from "lucide-react"

import { lowerChamber } from "@/lib/filters"
import { ChamberPills } from "@/components/chamber-pills"
import { Button } from "@/components/ui/button"
import { CardFooter } from "@/components/ui/card"

// The standard foot of a home card (Brendan, 2026-09-07): the chamber pills
// at the left where the card has a chamber to pick, and the circle arrow at
// the right, into the card's own page — right at rest, up-right on hover.
// The jurisdiction names the pills (House or Assembly, then Senate); with no
// `state` the two are House and Senate.
export function CardFoot({
  chamber,
  onChamber,
  state,
  chambers,
  href,
  label,
  children,
}: {
  chamber?: string
  onChamber?: (chamber: string) => void
  /** The jurisdiction, for the lower chamber's name. */
  state?: string
  /** The pills, when they are not the jurisdiction's two. */
  chambers?: string[]
  href: string
  label: string
  /** Anything else the foot carries at the left, in place of the pills. */
  children?: React.ReactNode
}) {
  return (
    <CardFooter className="justify-between gap-2">
      {onChamber ? <ChamberPills value={chamber ?? ""} onChange={onChamber} chambers={chambers ?? [lowerChamber(state), "Senate"]} /> : (children ?? <span />)}
      <Button variant="outline" size="icon" aria-label={label} title={label} className="group/foot shrink-0 rounded-full" nativeButton={false} render={<Link href={href} />}>
        <ArrowRight className="transition-transform duration-200 group-hover/foot:-rotate-45" />
      </Button>
    </CardFooter>
  )
}

"use client"

import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"

// The chamber pills a card's footer uses, shared: House (or Assembly) and
// Senate, one or none pressed (Brendan, 2026-09-01). The chambers are handed
// in (2026-09-12: the card foot names them from the jurisdiction), so the
// pills travel with no hook behind them.
export function ChamberPills({ value, onChange, chambers }: { value: string; onChange: (chamber: string) => void; chambers: string[] }) {
  return (
    <ToggleGroup value={value ? [value] : []} onValueChange={(next) => onChange(String(next?.[0] ?? ""))} variant="outline" spacing={1}>
      {chambers.map((name) => (
        // The pressed pill is the lit one — filled, in the foreground — and
        // the other sits dim, so the pair reads as a choice made rather than
        // two switched on (Brendan, 2026-09-07).
        <ToggleGroupItem
          key={name}
          value={name}
          className="text-muted-foreground hover:text-foreground aria-pressed:border-foreground aria-pressed:bg-foreground aria-pressed:text-background data-[state=on]:border-foreground data-[state=on]:bg-foreground data-[state=on]:text-background"
        >
          {name}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  )
}
